def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_pressure = 0.0
    rich_competitors = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_competitors += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                weight = 1.0
                if opp.get('no_water_days', 0) >= 1:
                    weight += 0.2
                if opp.get('hp', 10) <= 3:
                    weight += 0.2
                if prev.get('status') == 'lost':
                    weight -= 0.15
                desperate_pressure = max(desperate_pressure, bid * weight)

    if budget <= 0:
        return 0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 35)
        return min(budget, 18)

    scarcity = 1.0 - ((supply - 15.0) / 10.0)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = 22 + 18 * scarcity

    if hp <= 2:
        base += 22
    elif hp <= 4:
        base += 10

    if no_water_days >= 2:
        base += 18
    elif no_water_days >= 1:
        base += 10

    base += min(rich_competitors * 2.5, 8)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        target = max(base, avg_prev + 2, desperate_pressure + 1.5)
        if highest_prev >= DAILY_SALARY * 0.9 and hp > 4 and no_water_days == 0 and supply >= 20:
            target = min(target, DAILY_SALARY * 0.42)
    else:
        target = base

    if day >= 8:
        target += 4
    if day >= 9 and (hp <= 4 or no_water_days >= 1):
        target += 8

    reserve_floor = DAILY_SALARY * max(0, 10 - day) * 0.18
    if budget < reserve_floor:
        target *= 0.82
    if budget < DAILY_SALARY:
        target *= 0.9

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.78)

    target = min(target, budget)
    if target < 0:
        target = 0
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    import math
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0
    supply_tight = supply < 18
    if hp <= 2 or no_water_days >= 2:
        base = min(budget, DAILY_SALARY * 0.9)
        return min(base, max(DAILY_SALARY * 0.4, max_prev_bid + 2))
    else:
        if supply_tight:
            desired = max(DAILY_SALARY * 0.3, max_prev_bid * 1.15)
        else:
            desired = max(DAILY_SALARY * 0.2, max_prev_bid * 1.05 + 1)
        return min(budget, min(DAILY_SALARY * 0.75, desired))
